function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];

  const dfs = (i, j, steps) => {
    if (steps === k) {
      path.push(...grid[i][j].map(val => val));
      return;
    }

    for (const [dx, dy] of directions) {
      const x = i + dx;
      const y = j + dy;
      if (x >= 0 && x < N && y >= 0 && y < N && !visited[x][y]) {
        visited[x][y] = true;
        dfs(x, y, steps + 1);
        visited[x][y] = false;
      }
    }
  };

  let minPathLength = Infinity;
  let minPathValues = [];

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited = new Array(N).fill().map(() => new Array(N).fill(false));
      dfs(i, j, 0);
      if (path.length === k && path.length < minPathLength) {
        minPathLength = path.length;
        minPathValues = [...path];
      }
      path.pop();
    }
  }

  return minPathValues;
}

