  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (arr[j] < arr[i]) {
        dpDesc[i] = Math.max(dpDesc[i], dpDesc[j] + arr[i]);
      }
    }
  }

  // Find the maximum sum of bitonic subsequence
  let maxSum = 0;
  for (let i = 0; i < n; i++) {
