class MinHeap {
  constructor() {
    this.heap = [];
  }

  size() {
    return this.heap.length;
  }

  peek() {
    return this.heap[0];
  }

  push(value) {
    this.heap.push(value);
    this.bubbleUp();
  }

  pop() {
    const root = this.heap[0];
    this.heap[0] = this.heap.pop();
    this.bubbleDown();
    return root;
  }

  bubbleUp() {
    let index = this.size() - 1;
    while (index > 0 && this.heap[index] < this.heap[Math.floor((index - 1) / 2)]) {
      const [a, b] = this.heap[index];
      const [c, d] = this.heap[Math.floor((index - 1) / 2)];
