function is_nested(string){
    let balance = 0;
    let hasNested = false;

    for (let char of string) {
        if (char === '[') {
            balance++;
            if (balance > 1) {
                hasNested = true;
            }
        } else if (char === ']') {
            balance--;
            if (balance < 0) {
                return false;
            }
        }
    }

    return hasNested && balance === 0;
}

function is_nested(string){
  let depth = 0;
  let hasNested = false;

  for (let char of string) {
    if (char === '[') {
      depth++;
      if (depth > 1) {
        hasNested = true;
      }
    } else if (char === ']') {
      depth--;
    }
  }

  return hasNested && depth === 1;
}

