function union_elements(test_tup1, test_tup2) {
  // Convert tuples to arrays
  const arr1 = Array.from(test_tup1);
  const arr2 = Array.from(test_tup2);

  // Use Set to find unique elements and then spread into an array
  const uniqueElements = [...new Set([...arr1, ...arr2])];

  // Sort the array in ascending order
  uniqueElements.sort((a, b) => a - b);

  // Return the sorted array as a tuple
  return [...uniqueElements];
}

